def algorithm(func, dim, lb, ub, budget, rng):
    best_solution = None
    best_fitness = np.inf

    for _ in range(budget):
        x = rng.uniform(lb, ub, size=dim)

        v = rng.uniform(lb, ub, size=dim)

        while True:
            y = x + 0.1 * rng.normal(size=dim)

            y = np.clip(y, lb, ub)

            if func(y) < func(x):
                x = y

                if func(x) < best_fitness:
                    best_solution = x
                    best_fitness = func(x)

            elif rng.uniform(0, 1) > 0.9:
                break

    return best_solution
